#!/bin/bash
# land-lint-zero.sh — The lint ceiling reaches the floor.
#
# All eight eslint errors fixed (every one an `any` at a boundary: the JWT
# decode, two JSON parses, three untyped API returns) and the ceiling
# ratcheted 8 -> 0. From here, the next `any` at a boundary is a failed
# build, not a debt entry.
#
# WEB ONLY. Push and Vercel takes it.
set -euo pipefail

cd "$(dirname "$0")"
[ -d together-city-react ] || { echo "!! Run this from the Together-Ai repo root."; exit 1; }

LOG="$(git log --oneline -40)"
MARK="Medical trades the weather for the environment"
case "$LOG" in
  *"$MARK"*) ;;
  *) echo "!! This patch applies on top of \"$MARK\" — run land-gradient-environment.sh first."; exit 1 ;;
esac
NEEDS="The lint ceiling reaches the floor"
case "$LOG" in
  *"$NEEDS"*) echo "== \"$NEEDS\" is already here. Nothing to do."; exit 0 ;;
esac
DIRTY="$(git status --porcelain | grep -Ev '^\?\? (land-.*\.sh|push-.*\.sh|.*\.patch)$' || true)"
if [ -n "$DIRTY" ]; then
  echo "!! Working tree is dirty. Commit or stash first:"; echo "$DIRTY"; exit 1
fi

PATCH="$(mktemp "${TMPDIR:-/tmp}/lintzero.XXXXXX")"
trap 'rm -f "$PATCH"' EXIT
cat <<'B64EOF' | tr -d '\n' | openssl base64 -d -A > "$PATCH"

B64EOF

WANT="6498061526c03973bc2b0cef7ced615725e4bcd59c5fb7ccb28b9cda0eecb459"
GOT="$(shasum -a 256 "$PATCH" | awk '{print $1}')"
[ "$GOT" = "$WANT" ] || { echo "!! Patch is corrupt."; echo "   want $WANT"; echo "   got  $GOT"; exit 1; }
echo "== patch verified"
git apply --check -C1 "$PATCH" || { echo "!! Patch does not apply cleanly. Nothing written."; exit 1; }
git am --keep-cr -C1 < "$PATCH"
echo "== committed"

cd together-city-react
npx tsc --noEmit
npx vitest run
npx eslint src || true
node scripts/lint-ceiling.mjs
node scripts/dead-export-audit.mjs
node scripts/motion-ceiling.mjs
node scripts/a11y-audit.mjs
node scripts/nav-audit.mjs
npx vite build
cd ..

echo
echo "==============================================================="
echo " Landed: $NEEDS — push and Vercel ships it."
echo " eslint now reports 0 errors and the ceiling is 0. The 33"
echo " warnings remain by design; they are hygiene, not holes."
echo "==============================================================="
